SourceCode.Declaration:
/// <summary>
/// The answer: SignedInElsewhere when another device has since signed in as this worker - the app then signs out.
/// OtherDevicePendingJobs / OtherDevicePendingCounts (peekSession): the worker's unfinished work on the device
/// that last held the session, as it last reported it - the app asks before taking over.
/// </summary>
[DataContractAttribute]
class HSMobileOpsSessionResponse
{
    boolean     success;
    str         errorCode;
    str         message;
    boolean     signedInElsewhere;
    int         otherDevicePendingJobs;
    int         otherDevicePendingCounts;
    utcdatetime otherDeviceReportedUtc;
}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('SignedInElsewhere')]
public boolean parmSignedInElsewhere(boolean _value = signedInElsewhere)
{
    signedInElsewhere = _value;
    return signedInElsewhere;
}

[DataMemberAttribute('OtherDevicePendingJobs')]
public int parmOtherDevicePendingJobs(int _value = otherDevicePendingJobs)
{
    otherDevicePendingJobs = _value;
    return otherDevicePendingJobs;
}

[DataMemberAttribute('OtherDevicePendingCounts')]
public int parmOtherDevicePendingCounts(int _value = otherDevicePendingCounts)
{
    otherDevicePendingCounts = _value;
    return otherDevicePendingCounts;
}

[DataMemberAttribute('OtherDeviceReportedUtc')]
public utcdatetime parmOtherDeviceReportedUtc(utcdatetime _value = otherDeviceReportedUtc)
{
    otherDeviceReportedUtc = _value;
    return otherDeviceReportedUtc;
}
